"""Meridian CRM 4.2 permission-check migration."""

_VALID_ACTIONS = frozenset({"READ", "CREATE", "UPDATE", "DELETE", "EXPORT"})


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform action on object and record."""
    if action not in _VALID_ACTIONS:
        return False

    role_id = user.get("ROLE_ID", "")
    permission = None

    # Preserve supplied rule-file order; the first matching row is authoritative.
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            permission = row
            break

    # Missing permission rows deny every role, including ADMIN.
    if permission is None:
        return False

    # DELETE requires a record that is not already soft-deleted.
    # Blank or missing CHAR(1) boolean values have legacy value N.
    if action == "DELETE":
        delete_flag = record.get("DEL_FLG", "")
        if delete_flag not in ("", "N"):
            return False

    # ADMIN bypasses scope only after a matching permission row is found.
    if role_id == "ADMIN":
        return True

    scope = permission.get("scope", "")
    if scope == "ALL":
        return True
    if scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if scope == "OWN":
        return record.get("OWNER_UID", "") == user.get("USR_ID", "")
    return False
